        { t: 'hallucination', m: B('النموذج بيقول معلومة غلط بثقة', 'the model stating something false with confidence'), ex: 'an invented order number' },
        { t: 'Batch API', m: B('إرسال طلبات كتير تتعالج بعدين بتكلفة أقل', 'sending many requests processed later at lower cost'), ex: 'client.messages.batches.create(...)' },
        { t: 'local model', m: B('نموذج AI بيشتغل على جهازك من غير نت', 'an AI model running on your own machine, offline'), ex: 'Ollama, llama3.2' },
        { t: 'Ollama', m: B('برنامج بيشغّل نماذج AI مفتوحة على جهازك', 'a program running open AI models on your machine'), ex: 'ollama pull llama3.2' }
